const capabilities = { nativeScreen: true, taskDelivery: true, taskCompletion: true, taskCancellation: true, usage: true, interactiveInterventions: true, terminalHistory: true };
const profile = { models: ["synthetic/pi"], thinkingLevel: "medium" as const, harness: "pi" as const };
const profiles: ExecutionProfileConfig = { schemaVersion: 2, profiles: { "pi-medium": profile } };
function roleDefinition(name: "worker" | "reviewer"): RoleDefinition { return { description: `Synthetic ${name}`, tools: ["read"], instructions: `Act as ${name}.`, contextPolicy: "project", childExtensionContributions: [] }; }
const catalog: RoleCatalog = { schemaVersion: 4, roles: { worker: roleDefinition("worker"), reviewer: roleDefinition("reviewer") } };
const callPolicy: CallPolicy = { modes: { ops: { targets: { worker: { profiles: ["pi-medium"] }, reviewer: { profiles: ["pi-medium"] } } } }, roles: {} };
function syntheticGcConfig(): MeshGcConfig { return { contextHeadroomTokens: 32768, periodicIntervalMs: 5000, activityHeartbeatMs: 2000, activityStaleMs: 10000, roles: { worker: { collectAt: 6, retain: 3, pressureFloor: 1 }, reviewer: { collectAt: 3, retain: 1, pressureFloor: 1 } } }; }
const withRoot = (run: (root: string) => Promise<void>) => withTemporaryRoot("mesh-gc-", run);
function createTask(root: string, meshId: string, agentId: string, prompt: string, reservationId?: string, requestedTaskId?: string) { return createStoreTask(root, meshId, agentId, prompt, { requesterEndpointId: `root:${meshId}` }, reservationId, requestedTaskId); }
function tmuxExec(alive = new Set<string>()): CommandExecutor { return async (_command, args) => { const operation = args.find(item => ["display-message", "kill-window", "list-panes", "has-session"].includes(item)); if (operation === "display-message") return { stdout: "10\n", stderr: "", code: 0 }; if (operation === "kill-window") { const target = args.at(-1)!; alive.delete(target.replace("@", "%")); return { stdout: "", stderr: "", code: 0 }; } if (operation === "list-panes") return { stdout: [...alive].map(id => `${id}\t0`).join("\n"), stderr: "", code: 0 }; if (operation === "has-session") return { stdout: "", stderr: "", code: 0 }; return { stdout: "", stderr: "", code: 0 }; }; }
async function fixture(root: string, budgets = { maxLiveAgents: 20, maxConcurrentTasks: 20, maxTasksPerMesh: 100 }) { const mesh = await initializeMesh(root, { rootSessionId: "root", recoverable: true, budgets }); const lease = await attachRootMesh(root, mesh.meshId, { rootSessionId: "root", budgets }); const epoch = await ensurePolicyEpoch(root, mesh.meshId, { mode: "ops", catalog, profiles, callPolicy }); return { mesh, lease, epoch }; }
async function prepareRole(root: string, meshId: string, epochId: string, reservationId: string, role: "worker" | "reviewer" = "worker") { return prepareAgent(root, meshId, { reservationId, role, selectedProfile: "pi-medium", harness: "pi", cwd: root, roleSnapshot: roleDefinition(role), profileSnapshot: profile, launchEnvelope: "pending", epochId, provenance: { creatorSessionId: "root" }, capabilities }); }
async function publishRole(root: string, meshId: string, epoch: Awaited<ReturnType<typeof fixture>>["epoch"], prepared: Awaited<ReturnType<typeof prepareRole>>, role: "worker" | "reviewer" = "worker") { const envelope = buildLaunchEnvelope({ meshId, agentId: prepared.agentId, epochId: epoch.epochId, role, snapshot: epoch, childExtensions: { worker: [], reviewer: [] } }); const envelopePath = join(prepared.paths.directory, "launch-envelope.json"); await writeFile(envelopePath, JSON.stringify(envelope)); const paneId = `%${prepared.agentId}`; await publishAgent(root, meshId, prepared.paths, { agentId: prepared.agentId, epochId: epoch.epochId, role, selectedProfile: "pi-medium", harness: "pi", cwd: root, roleSnapshot: roleDefinition(role), profileSnapshot: profile, launchEnvelope: envelopePath, tmux: { socket: "/tmp/tmux", serverPid: "10", sessionId: "$1", sessionName: "mesh", windowId: `@${prepared.agentId}`, paneId, windowName: role }, capabilities, creatorSessionId: "root" }); return { ...prepared, paneId }; }
async function publishedAdmissionLaunch(root: string, f: Awaited<ReturnType<typeof fixture>>, reservationId: string) { return publishRole(root, f.mesh.meshId, f.epoch, await prepareRole(root, f.mesh.meshId, f.epoch.epochId, reservationId)); }
async function agent(root: string, meshId: string, epochId: string, role: "worker" | "reviewer", phaseSince: string, context: ReturnType<typeof availableContext> = availableContext(10, 100_000, 100)) { const reservation = await reserveMeshCapacity(root, meshId, "new-agent-task"); const f = await fixtureForEpoch(root, meshId, epochId); const prepared = await prepareRole(root, meshId, epochId, reservation.reservationId, role); const published = await publishRole(root, meshId, f.epoch, prepared, role); await patchAgentStatus(root, meshId, prepared.agentId, { state: "idle", bridgeReady: true }); const runtimeId = randomUUID(); await bindAgentRuntime(root, meshId, prepared.agentId, { runtimeId, kind: "external" }); await publishAgentActivity(root, meshId, prepared.agentId, { runtimeId, phase: "idle", acceptingTask: true, pendingMessages: false, phaseSince, observedAt: new Date().toISOString(), heartbeatAt: new Date().toISOString(), context }); return { ...published, runtimeId }; }
async function fixtureForEpoch(root: string, meshId: string, epochId: string) { const epoch = await (await import("../extensions_src/utilities/orchestration_store.ts")).readPolicyEpoch(root, meshId, epochId); return { epoch }; }

void test("stop reasons enforce trimmed UTF-8 byte bounds", () => { assert.equal(validateStopReason("  intentional stop  "), "intentional stop"); assert.equal(Buffer.byteLength(validateStopReason("界".repeat(170)), "utf8"), 510); assert.throws(() => validateStopReason("   "), /1-512 UTF-8 bytes/u); assert.throws(() => validateStopReason("界".repeat(171)), /1-512 UTF-8 bytes/u); });

void test("periodic GC retires context-bound agents and deterministically retains each role's newest idle wave", async () => withRoot(async root => { const f = await fixture(root); const alive = new Set<string>(); const workers = []; for (let index = 0; index < 6; index += 1) { const item = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", `2026-08-09T12:00:0${index}.000Z`); workers.push(item); alive.add(item.paneId); } const retiring = await agent(root, f.mesh.meshId, f.epoch.epochId, "reviewer", "2026-08-09T11:00:00.000Z", availableContext(868, 1000, 100)); alive.add(retiring.paneId); const result = await runPeriodicAgentGc({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" }); assert.deepEqual(result.confirmed, [retiring.agentId, workers[0]!.agentId, workers[1]!.agentId, workers[2]!.agentId]); for (const item of result.confirmed) assert.equal((await readAgentSnapshot(root, f.mesh.meshId, item)).status.state, "stopped"); const notices = await listPendingTuiNotices(root, f.mesh.meshId, { endpointId: `root:${f.mesh.meshId}` }); assert.equal(notices.length, 1); assert.equal(notices[0]?.kind, "gc-stop"); if (notices[0]?.kind === "gc-stop") { assert.equal(notices[0].payload.gcPassId, result.gcPassId); assert.deepEqual(notices[0].payload.confirmed.map(item => item.agentId), [...result.confirmed].sort()); assert.deepEqual({ failed: notices[0].payload.failedCount, pending: notices[0].payload.pendingCount }, { failed: 0, pending: 0 }); } await unlink(join(root, "meshes", f.mesh.meshId, "notices", `${notices[0]!.noticeId}.json`)); await recoverPendingAgentStops({ stateRoot: root, meshId: f.mesh.meshId, exec: tmuxExec(alive), tmux: "tmux" }); assert.equal((await listPendingTuiNotices(root, f.mesh.meshId, { endpointId: `root:${f.mesh.meshId}` })).length, 1); assert.deepEqual(await Promise.all(workers.slice(3).map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(value => value.status.state))), ["idle", "idle", "idle"]); }));

// Given a periodic retain victim selected while four same-role agents are reusable, when another same-role agent becomes busy before the final claim, the victim remains reusable because the fresh count is already at retain.
void test("periodic retain rechecks same-role reuse at the final claim boundary", async () => withRoot(async root => { const f = await fixture(root); const gc = syntheticGcConfig(); gc.roles.worker = { collectAt: 4, retain: 3, pressureFloor: 1 }; const workers: Awaited<ReturnType<typeof agent>>[] = []; for (let index = 0; index < 4; index += 1) workers.push(await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", `2026-08-09T12:00:0${index}.000Z`)); let interleaved = false; const result = await runPeriodicAgentGc({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc, exec: tmuxExec(new Set(workers.map(item => item.paneId))), tmux: "tmux", beforeClaim: async ({ source }) => { if (source === "gc-role" && !interleaved) { interleaved = true; await createTask(root, f.mesh.meshId, workers[3]!.agentId, "same-role reuse wins before claim"); } } }); assert.equal(interleaved, true); assert.deepEqual(result.confirmed, []); assert.deepEqual(await Promise.all([workers[0]!, workers[3]!].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(snapshot => ({ state: snapshot.status.state, stop: snapshot.stop })))), [{ state: "idle", stop: null }, { state: "busy", stop: null }]); }));

// Given an unavailable notice store, GC remains authoritative and succeeds; later recovery can deterministically retry notice reconciliation.
void test("notice persistence is auxiliary to GC lifecycle", async () => withRoot(async root => { const f = await fixture(root); const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "reviewer", new Date().toISOString(), availableContext(868, 1000, 100)); const alive = new Set([target.paneId]); await writeFile(join(root, "meshes", f.mesh.meshId, "notices"), "blocked"); const result = await runPeriodicAgentGc({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" }); assert.deepEqual(result.confirmed, [target.agentId]); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, target.agentId)).status.state, "stopped"); const explicit = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); await requestAgentStop(root, f.mesh.meshId, explicit.agentId, { source: "peer", reason: "notice remains auxiliary", requesterEndpointId: "agent:requester" }); await recoverPendingAgentStops({ stateRoot: root, meshId: f.mesh.meshId, exec: tmuxExec(), tmux: "tmux" }); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, explicit.agentId)).status.state, "stopped"); }));

void test("task admission and an idle GC claim have exactly one durable winner", async () => withRoot(async root => { const f = await fixture(root); const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const snapshot = await readAgentSnapshot(root, f.mesh.meshId, target.agentId); const sequence = (await import("../extensions_src/utilities/orchestration_activity.ts")).readAgentActivity(root, f.mesh.meshId, target.agentId).then(value => value!.sequence); const [task, claim] = await Promise.allSettled([createTask(root, f.mesh.meshId, target.agentId, "race"), claimIdleAgentForStop(root, f.mesh.meshId, target.agentId, { source: "gc-role", reason: "Role worker exceeded its idle retention policy", activitySequence: await sequence, staleMs: 10_000 })]); const taskWon = task.status === "fulfilled"; const claimWon = claim.status === "fulfilled" && claim.value !== undefined; assert.notEqual(taskWon, claimWon); const final = await readAgentSnapshot(root, f.mesh.meshId, target.agentId); assert.equal(taskWon ? final.status.state : final.stop?.state, taskWon ? "busy" : "requested"); assert.equal(snapshot.activity.acceptingTask, true); }));

// Given explicit, GC, and launch-failure stop intent crashes after stop.json is durable but before status.json changes, when root recovery crosses termination, each first writer's durable terminal outcome is confirmed.
void test("stop recovery repairs intent persistence crash windows and preserves terminal outcome", async () => withRoot(async root => { const f = await fixture(root); const explicit = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const gc = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const launchFailure = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const crash = async () => { throw new Error("injected crash after stop request persistence"); }; await assert.rejects(requestAgentStop(root, f.mesh.meshId, explicit.agentId, { source: "peer", reason: "explicit crash recovery", afterRequestPersisted: crash }), /injected crash/u); const activity = await (await import("../extensions_src/utilities/orchestration_activity.ts")).readAgentActivity(root, f.mesh.meshId, gc.agentId); await assert.rejects(claimIdleAgentForStop(root, f.mesh.meshId, gc.agentId, { source: "gc-role", reason: "GC crash recovery", activitySequence: activity!.sequence, staleMs: 10_000, afterRequestPersisted: crash }), /injected crash/u); await assert.rejects(requestAgentStop(root, f.mesh.meshId, launchFailure.agentId, { source: "recovery", reason: "bridge launch failed", terminalState: "failed", afterRequestPersisted: crash }), /injected crash/u); assert.deepEqual(await Promise.all([explicit, gc, launchFailure].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(value => ({ lifecycle: value.status.state, stop: value.stop?.state, terminalState: value.stop?.terminalState ?? "stopped" })))), [{ lifecycle: "idle", stop: "requested", terminalState: "stopped" }, { lifecycle: "idle", stop: "requested", terminalState: "stopped" }, { lifecycle: "idle", stop: "requested", terminalState: "failed" }]); const alive = new Set([explicit.paneId, gc.paneId, launchFailure.paneId]); const recovered = await recoverPendingAgentStops({ stateRoot: root, meshId: f.mesh.meshId, exec: tmuxExec(alive), tmux: "tmux" }); assert.equal(recovered.confirmed, 3); assert.deepEqual(await Promise.all([explicit, gc, launchFailure].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(value => ({ lifecycle: value.status.state, stop: value.stop?.state, reason: value.status.exitReason })))), [{ lifecycle: "stopped", stop: "confirmed", reason: "explicit crash recovery" }, { lifecycle: "stopped", stop: "confirmed", reason: "GC crash recovery" }, { lifecycle: "failed", stop: "confirmed", reason: "bridge launch failed" }]); }));

// Given a stop caller delayed before durable request acquisition, when another attempt fails and restores or reuses the agent, the delayed generation cannot create a replacement request or kill; a later fresh call still can.
void test("delayed pre-claim stop callers are fenced by their initial agent lifecycle generation", async () => withRoot(async root => { const f = await fixture(root); const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const initial = await readAgentSnapshot(root, f.mesh.meshId, target.agentId); const delayedLifecycle = { statusUpdatedAt: initial.status.updatedAt, runtimeId: target.runtimeId }; const replacementRuntimeId = randomUUID(); await bindAgentRuntime(root, f.mesh.meshId, target.agentId, { runtimeId: replacementRuntimeId, kind: "external" }); const now = new Date().toISOString(); await publishAgentActivity(root, f.mesh.meshId, target.agentId, { runtimeId: replacementRuntimeId, phase: "starting", acceptingTask: false, pendingMessages: false, phaseSince: now, observedAt: now, heartbeatAt: now, context: availableContext(10, 100_000, 100) }); await publishAgentActivity(root, f.mesh.meshId, target.agentId, { runtimeId: replacementRuntimeId, phase: "idle", acceptingTask: true, pendingMessages: false, phaseSince: now, observedAt: now, heartbeatAt: now, context: availableContext(10, 100_000, 100) }); let kills = 0; const failing: CommandExecutor = async (_command, args) => { if (args.includes("display-message")) return { stdout: "10\n", stderr: "", code: 0 }; if (args.includes("kill-window")) { kills += 1; return { stdout: "", stderr: "kill failed", code: 1 }; } if (args.includes("list-panes")) return { stdout: `${target.paneId}\t0\n`, stderr: "", code: 0 }; if (args.includes("has-session")) return { stdout: "", stderr: "", code: 0 }; return { stdout: "", stderr: "", code: 0 }; }; await assert.rejects(stopMeshAgentWithDisposition({ stateRoot: root, meshId: f.mesh.meshId, agentId: target.agentId, source: "peer", reason: "first attempt", exec: failing, tmux: "tmux" }), /kill failed|Could not stop/u); await createTask(root, f.mesh.meshId, target.agentId, "reuse after failed stop"); await assert.rejects(requestAgentStop(root, f.mesh.meshId, target.agentId, { source: "peer", reason: "delayed stale attempt", initialLifecycle: delayedLifecycle }), /lifecycle observation is stale/u); assert.equal(kills, 1); const staleSnapshot = await readAgentSnapshot(root, f.mesh.meshId, target.agentId); assert.equal(staleSnapshot.stop?.state, "failed"); const alive = new Set([target.paneId]); const fresh = await stopMeshAgentWithDisposition({ stateRoot: root, meshId: f.mesh.meshId, agentId: target.agentId, source: "peer", reason: "fresh intentional stop", exec: tmuxExec(alive), tmux: "tmux" }); assert.equal(fresh.snapshot.stop?.state, "confirmed"); assert.equal(alive.has(target.paneId), false); }));

void test("durable stop requests keep the first writer and recovery confirms a dead pane with the winning reason", async () => withRoot(async root => { const f = await fixture(root); const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const first = await requestAgentStop(root, f.mesh.meshId, target.agentId, { source: "peer", reason: "first reason", requesterEndpointId: "root:test" }); const second = await requestAgentStop(root, f.mesh.meshId, target.agentId, { source: "shutdown", reason: "later reason", terminalState: "failed" }); assert.equal(second.request.stopRequestId, first.request.stopRequestId); assert.equal(second.request.reason, "first reason"); assert.equal(second.request.terminalState, undefined); assert.deepEqual(await listPendingTuiNotices(root, f.mesh.meshId, { endpointId: `root:${f.mesh.meshId}` }), []); await recoverPendingAgentStops({ stateRoot: root, meshId: f.mesh.meshId, exec: tmuxExec(), tmux: "tmux" }); const recovered = await readAgentSnapshot(root, f.mesh.meshId, target.agentId); assert.deepEqual({ state: recovered.status.state, reason: recovered.stop?.reason, source: recovered.stop?.source }, { state: "stopped", reason: "first reason", source: "peer" }); const explicitNotices = await listPendingTuiNotices(root, f.mesh.meshId, { endpointId: `root:${f.mesh.meshId}` }); assert.equal(explicitNotices.length, 1); assert.equal(explicitNotices[0]?.kind, "explicit-stop"); const persistedTerminal = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const pending = await requestAgentStop(root, f.mesh.meshId, persistedTerminal.agentId, { source: "peer", reason: "persisted terminal boundary" }); await patchAgentStatus(root, f.mesh.meshId, persistedTerminal.agentId, { state: "stopped", exitReason: pending.request.reason }); await recoverPendingAgentStops({ stateRoot: root, meshId: f.mesh.meshId, exec: tmuxExec(), tmux: "tmux" }); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, persistedTerminal.agentId)).stop?.state, "confirmed"); const mismatch = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); await requestAgentStop(root, f.mesh.meshId, mismatch.agentId, { source: "peer", reason: "identity mismatch stays pending" }); const mismatchExec: CommandExecutor = async () => ({ stdout: "99\n", stderr: "", code: 0 }); await readReconciledAgentSnapshot(mismatchExec, "tmux", root, f.mesh.meshId, mismatch.agentId); const retained = await readAgentSnapshot(root, f.mesh.meshId, mismatch.agentId); assert.deepEqual({ lifecycle: retained.status.state, stop: retained.stop?.state }, { lifecycle: "stopping", stop: "requested" }); await recoverPendingAgentStops({ stateRoot: root, meshId: f.mesh.meshId, exec: tmuxExec(), tmux: "tmux" }); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, mismatch.agentId)).stop?.state, "confirmed"); }));

void test("pressure GC tries another eligible victim after a definitive first-victim failure", async () => withRoot(async root => { const budgets = { maxLiveAgents: 2, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }; const f = await fixture(root, budgets); const first = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const second = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); const alive = new Set([first.paneId, second.paneId]); let firstKill = true; const exec: CommandExecutor = async (_command, args) => { const operation = args.find(item => ["display-message", "kill-window", "list-panes", "has-session"].includes(item)); if (operation === "display-message") return { stdout: "10\n", stderr: "", code: 0 }; if (operation === "kill-window") { if (firstKill) { firstKill = false; return { stdout: "", stderr: "kill failed", code: 1 }; } alive.delete(args.at(-1)!.replace("@", "%")); return { stdout: "", stderr: "", code: 0 }; } if (operation === "list-panes") return { stdout: [...alive].map(id => `${id}\t0`).join("\n"), stderr: "", code: 0 }; return { stdout: "", stderr: "", code: 0 }; }; const reservation = await reserveNewAgentCapacityWithPressure({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec, tmux: "tmux" }); assert.equal(reservation.state, "pending"); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, first.agentId)).stop?.state, "failed"); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, second.agentId)).status.state, "stopped"); }));

void test("pressure GC reclaims one eligible idle agent before one bounded live-capacity reservation retry", async () => withRoot(async root => { const budgets = { maxLiveAgents: 2, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }; const f = await fixture(root, budgets); const alive = new Set<string>(); const first = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const second = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); alive.add(first.paneId); alive.add(second.paneId); await assert.rejects(reserveNewAgentCapacityWithPressure({ stateRoot: root, meshId: f.mesh.meshId, leaseId: randomUUID(), gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" }), /root lease owner/u); assert.deepEqual(await Promise.all([first, second].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(value => value.status.state))), ["idle", "idle"]); const reservation = await reserveNewAgentCapacityWithPressure({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" }); assert.equal(reservation.state, "pending"); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, first.agentId)).status.state, "stopped"); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, second.agentId)).status.state, "idle"); }));

// Given a pressure-floor victim selected while two same-role agents are reusable, when the other agent becomes busy before the final reserve-or-claim boundary, pressure is rejected and the victim remains reusable at the floor.
void test("pressure floor rechecks same-role reuse at the final claim boundary", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 2, maxConcurrentTasks: 6, maxTasksPerMesh: 20 }); const victim = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const peer = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); let interleaved = false; await assert.rejects(reserveNewAgentCapacityWithPressure({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(new Set([victim.paneId, peer.paneId])), tmux: "tmux" }, undefined, async () => { if (!interleaved) { interleaved = true; await createTask(root, f.mesh.meshId, peer.agentId, "same-role reuse wins before pressure-floor claim"); } }), /no pressure GC candidate/u); assert.equal(interleaved, true); assert.deepEqual(await Promise.all([victim, peer].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(snapshot => ({ state: snapshot.status.state, stop: snapshot.stop })))), [{ state: "idle", stop: null }, { state: "busy", stop: null }]); }));

// Given capacity released concurrently after victim selection, when pressure GC reaches the claim boundary, the deterministic retry succeeds without evicting the selected idle peer.
