// Given a requester that becomes non-live after admission processing starts, when pressure GC reaches its exact pre-claim guard, the request is cancelled before any victim claim.
void test("pressure admission revalidates requester liveness immediately before each victim claim", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 3, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }); const victim = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const spare = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.500Z"); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const requestId = randomUUID(); await requestPressureAdmission(root, f.mesh.meshId, { requestId, requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }); const alive = new Set([victim.paneId, spare.paneId, requester.paneId]); let sessionChecks = 0; let kills = 0; const exec: CommandExecutor = async (_command, args) => { const operation = args.find(item => ["display-message", "kill-window", "list-panes", "has-session"].includes(item)); if (operation === "display-message") return { stdout: "10\n", stderr: "", code: 0 }; if (operation === "list-panes") return { stdout: [...alive].map(id => `${id}\t0`).join("\n"), stderr: "", code: 0 }; if (operation === "has-session") { sessionChecks += 1; if (sessionChecks === 2) await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "stopping", exitReason: "requester stopping" }); return { stdout: "", stderr: "", code: 0 }; } if (operation === "kill-window") { kills += 1; return { stdout: "", stderr: "", code: 0 }; } return { stdout: "", stderr: "", code: 0 }; }; assert.equal(await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec, tmux: "tmux" }), 1); assert.equal(kills, 0); assert.equal((await readPressureAdmission(root, f.mesh.meshId, requestId)).state, "cancelled"); assert.deepEqual(await Promise.all([victim, spare].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(value => value.status.state))), ["idle", "idle"]); }));

