// Given cancellation and a concurrent capacity release after requester liveness is checked, when pressure reaches its locked final boundary, cancellation prevents a claim and released capacity is reserved without evicting a peer.
void test("pressure final boundary atomically fences cancellation and observes released capacity", async () => withRoot(async root => { const setup = async (maxLiveAgents = 3) => { const f = await fixture(root, { maxLiveAgents, maxConcurrentTasks: 7, maxTasksPerMesh: 30 }); const victim = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const spare = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.500Z"); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const requestId = randomUUID(); await requestPressureAdmission(root, f.mesh.meshId, { requestId, requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }); return { f, victim, spare, requester, requestId }; }; const cancelled = await setup(); let checks = 0; let kills = 0; const cancelExec: CommandExecutor = async (_command, args) => { const operation = args.find(item => ["display-message", "kill-window", "list-panes", "has-session"].includes(item)); if (operation === "display-message") { checks += 1; if (checks === 3) await (await import("../extensions_src/utilities/orchestration_admission.ts")).cancelPressureAdmission(root, cancelled.f.mesh.meshId, cancelled.requestId, "caller cancelled at final boundary"); return { stdout: "10\n", stderr: "", code: 0 }; } if (operation === "list-panes") return { stdout: [cancelled.victim.paneId, cancelled.spare.paneId, cancelled.requester.paneId].map(id => `${id}\t0`).join("\n"), stderr: "", code: 0 }; if (operation === "has-session") return { stdout: "", stderr: "", code: 0 }; if (operation === "kill-window") { kills += 1; return { stdout: "", stderr: "", code: 0 }; } return { stdout: "", stderr: "", code: 0 }; }; await processPressureAdmissions({ stateRoot: root, meshId: cancelled.f.mesh.meshId, leaseId: cancelled.f.lease.leaseId, gc: syntheticGcConfig(), exec: cancelExec, tmux: "tmux" }); assert.equal(kills, 0); assert.equal((await readPressureAdmission(root, cancelled.f.mesh.meshId, cancelled.requestId)).state, "cancelled"); const released = await setup(4); const blocker = await reserveMeshCapacity(root, released.f.mesh.meshId, "new-agent-task"); checks = 0; const alive = new Set([released.victim.paneId, released.spare.paneId, released.requester.paneId]); const base = tmuxExec(alive); const releaseExec: CommandExecutor = async (command, args) => { if (args.includes("display-message")) { checks += 1; if (checks === 3) await releaseMeshReservation(root, released.f.mesh.meshId, blocker.reservationId, "capacity released at final boundary"); } return base(command, args); }; await processPressureAdmissions({ stateRoot: root, meshId: released.f.mesh.meshId, leaseId: released.f.lease.leaseId, gc: syntheticGcConfig(), exec: releaseExec, tmux: "tmux" }); assert.equal((await readPressureAdmission(root, released.f.mesh.meshId, released.requestId)).state, "succeeded"); assert.deepEqual(await Promise.all([released.victim, released.spare].map(item => readAgentSnapshot(root, released.f.mesh.meshId, item.agentId).then(value => value.status.state))), ["idle", "idle"]); }));

// Given a requester death in the unavoidable kill window, when reclamation finishes before success settlement, the admission is cancelled and its deterministic reservation is released rather than stranding capacity.
void test("pressure admission revalidates requester after reclamation before settlement", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 3, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }); const victim = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const spare = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.500Z"); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const requestId = randomUUID(); await requestPressureAdmission(root, f.mesh.meshId, { requestId, requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }); const alive = new Set([victim.paneId, spare.paneId, requester.paneId]); const base = tmuxExec(alive); const exec: CommandExecutor = async (command, args) => { const result = await base(command, args); if (args.includes("kill-window") && args.at(-1) === `@${victim.agentId}`) await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "stopped", exitReason: "requester exited during reclamation" }); return result; }; assert.equal(await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec, tmux: "tmux" }), 1); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, victim.agentId)).status.state, "stopped"); assert.equal((await readPressureAdmission(root, f.mesh.meshId, requestId)).state, "cancelled"); assert.equal((await readMeshReservation(root, f.mesh.meshId, requestId)).state, "released"); }));

// Given temporarily unavailable exact tmux evidence, when successive maintenance ticks inspect pressure demand, the request stays pending without GC until a later live observation permits processing.
void test("pressure maintenance defers unavailable requester evidence and retries on the next tick", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 3, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }); const victim = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const spare = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.500Z"); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const requestId = randomUUID(); await requestPressureAdmission(root, f.mesh.meshId, { requestId, requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }); let displays = 0; const unavailable: CommandExecutor = async (_command, args) => { const operation = args.find(item => ["display-message", "list-panes", "has-session"].includes(item)); if (operation === "display-message") return ++displays === 1 ? { stdout: "10\n", stderr: "", code: 0 } : { stdout: "", stderr: "temporary inspection failure", code: 2 }; if (operation === "list-panes") return { stdout: `${requester.paneId}\t0\n`, stderr: "", code: 0 }; return { stdout: "", stderr: "", code: 0 }; }; assert.equal(await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: unavailable, tmux: "tmux" }), 0); assert.equal((await readPressureAdmission(root, f.mesh.meshId, requestId)).state, "processing"); assert.deepEqual(await Promise.all([victim, spare].map(item => readAgentSnapshot(root, f.mesh.meshId, item.agentId).then(value => value.status.state))), ["idle", "idle"]); const alive = new Set([victim.paneId, spare.paneId, requester.paneId]); assert.equal(await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" }), 1); assert.equal((await readPressureAdmission(root, f.mesh.meshId, requestId)).state, "succeeded"); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, victim.agentId)).status.state, "stopped"); }));

// Given requested and processing admissions whose durable endpoint bindings later go offline, one maintenance pass cancels each admission, admits later healthy demand, and still reaches periodic GC.
void test("stale pressure bindings are contained per admission so later admission and GC continue", async () => withRoot(async root => {
    const f = await fixture(root, { maxLiveAgents: 8, maxConcurrentTasks: 10, maxTasksPerMesh: 30 });
    const requested = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z");
    const processing = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z");
    const healthy = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:02.000Z");
    const gcTarget = await agent(root, f.mesh.meshId, f.epoch.epochId, "reviewer", "2026-08-09T12:00:03.000Z", availableContext(868, 1000, 100));
    for (const requester of [requested, processing, healthy]) await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" });
    const ids = { requested: "10000000-0000-4000-8000-000000000001", processing: "20000000-0000-4000-8000-000000000002", healthy: "f0000000-0000-4000-8000-000000000003" };
    const requestedEndpoint = await bindMeshEndpoint(root, f.mesh.meshId, { endpointId: `agent:${requested.agentId}`, kind: "agent", agentId: requested.agentId, harness: "pi", sessionId: "requested", sessionFile: join(root, "requested.jsonl") });
    const processingEndpoint = await bindMeshEndpoint(root, f.mesh.meshId, { endpointId: `agent:${processing.agentId}`, kind: "agent", agentId: processing.agentId, harness: "pi", sessionId: "processing", sessionFile: join(root, "processing.jsonl") });
    await requestPressureAdmission(root, f.mesh.meshId, { requestId: ids.processing, requesterAgentId: processing.agentId, requesterRuntimeId: processing.runtimeId, expectedBinding: { endpointId: processingEndpoint.endpointId, endpointSessionFile: processingEndpoint.sessionFile } });
    let displays = 0; const unavailable: CommandExecutor = async (_command, args) => { if (args.includes("display-message")) return ++displays === 1 ? { stdout: "10\n", stderr: "", code: 0 } : { stdout: "", stderr: "temporarily unavailable", code: 2 }; if (args.includes("list-panes")) return { stdout: `${processing.paneId}\t0\n`, stderr: "", code: 0 }; return { stdout: "", stderr: "", code: 0 }; };
    assert.equal(await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: unavailable, tmux: "tmux" }), 0);
    assert.equal((await readPressureAdmission(root, f.mesh.meshId, ids.processing)).state, "processing");
    await requestPressureAdmission(root, f.mesh.meshId, { requestId: ids.requested, requesterAgentId: requested.agentId, requesterRuntimeId: requested.runtimeId, expectedBinding: { endpointId: requestedEndpoint.endpointId, endpointSessionFile: requestedEndpoint.sessionFile } });
    await requestPressureAdmission(root, f.mesh.meshId, { requestId: ids.healthy, requesterAgentId: healthy.agentId, requesterRuntimeId: healthy.runtimeId });
    await setMeshEndpointOffline(root, f.mesh.meshId, requestedEndpoint.endpointId, requestedEndpoint); await setMeshEndpointOffline(root, f.mesh.meshId, processingEndpoint.endpointId, processingEndpoint);
    const alive = new Set([requested.paneId, processing.paneId, healthy.paneId, gcTarget.paneId]); const options = { stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" };
    assert.equal(await processPressureAdmissions(options), 3);
    assert.deepEqual(await Promise.all([ids.requested, ids.processing, ids.healthy].map(id => readPressureAdmission(root, f.mesh.meshId, id).then(value => value.state))), ["cancelled", "cancelled", "succeeded"]);
    const gc = await runPeriodicAgentGc(options); assert.equal(gc.confirmed.includes(gcTarget.agentId), true); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, gcTarget.agentId)).status.state, "stopped");
}));

void test("a nested current runtime gets one idempotent root-mediated pressure admission at live capacity", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 3, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }); const victim = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.000Z"); const spare = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:00.500Z"); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", "2026-08-09T12:00:01.000Z"); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const requestId = randomUUID(); const input = { requestId, requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }; const first = await requestPressureAdmission(root, f.mesh.meshId, input); const retry = await requestPressureAdmission(root, f.mesh.meshId, input); assert.equal(retry.requestId, first.requestId); const alive = new Set([victim.paneId, spare.paneId, requester.paneId]); await writeFile(join(root, "meshes", f.mesh.meshId, "notices"), "blocked"); assert.equal(await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(alive), tmux: "tmux" }), 1); const reservation = await awaitPressureAdmission(root, f.mesh.meshId, input); assert.equal(reservation.reservationId, requestId); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, victim.agentId)).status.state, "stopped"); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, requester.agentId)).status.state, "busy"); }));

// Given a root-created reservation whose admission caller survives a root crash, when pressure and generic reconciliation cross the durable store, the caller receives the original pending reservation while stale-runtime admissions are cancelled and released.
void test("pressure admission survives generic reconciliation only for its current requester runtime", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 4, maxConcurrentTasks: 5, maxTasksPerMesh: 20 }); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const input = { requestId: randomUUID(), requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }; await requestPressureAdmission(root, f.mesh.meshId, input); await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(new Set([requester.paneId])), tmux: "tmux" }); const protectedIds = await reconcilePressureAdmissions(root, f.mesh.meshId, async () => true); assert.deepEqual([...protectedIds], [input.requestId]); await reconcileMeshReservations(root, f.mesh.meshId, async () => "absent", protectedIds); const durable = await readMeshReservation(root, f.mesh.meshId, input.requestId); assert.deepEqual(await awaitPressureAdmission(root, f.mesh.meshId, input), durable); const stale = { requestId: randomUUID(), requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }; await requestPressureAdmission(root, f.mesh.meshId, stale); await processPressureAdmissions({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(new Set([requester.paneId])), tmux: "tmux" }); await bindAgentRuntime(root, f.mesh.meshId, requester.agentId, { runtimeId: randomUUID(), kind: "external" }); assert.deepEqual([...(await reconcilePressureAdmissions(root, f.mesh.meshId, async () => true))], []); assert.equal((await readPressureAdmission(root, f.mesh.meshId, stale.requestId)).state, "cancelled"); assert.equal((await readMeshReservation(root, f.mesh.meshId, stale.requestId)).state, "released"); }));

// Given a deterministic reservation in a pre-success crash window, generic reconciliation protects it only while both requester generation and pane are live; shutdown releases it, while committed capacity remains consumed.
void test("pressure crash windows and shutdown preserve only live unconsumed admissions", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 5, maxConcurrentTasks: 8, maxTasksPerMesh: 20 }); const requester = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); await patchAgentStatus(root, f.mesh.meshId, requester.agentId, { state: "busy" }); const input = { requestId: randomUUID(), requesterAgentId: requester.agentId, requesterRuntimeId: requester.runtimeId }; await requestPressureAdmission(root, f.mesh.meshId, input); await reserveMeshCapacity(root, f.mesh.meshId, "new-agent-task", undefined, input.requestId); assert.deepEqual([...(await reconcilePressureAdmissions(root, f.mesh.meshId, async () => true))], [input.requestId]); await reconcileMeshReservations(root, f.mesh.meshId, async () => "absent", new Set([input.requestId])); assert.equal((await readMeshReservation(root, f.mesh.meshId, input.requestId)).state, "pending"); await failOpenPressureAdmissions(root, f.mesh.meshId, "reload"); assert.equal((await readMeshReservation(root, f.mesh.meshId, input.requestId)).state, "released"); const committedInput = { ...input, requestId: randomUUID() }; await requestPressureAdmission(root, f.mesh.meshId, committedInput); const committed = await reserveMeshCapacity(root, f.mesh.meshId, "new-agent-task", undefined, committedInput.requestId); await prepareRole(root, f.mesh.meshId, f.epoch.epochId, committed.reservationId); await failOpenPressureAdmissions(root, f.mesh.meshId, "reload"); assert.equal((await readMeshReservation(root, f.mesh.meshId, committedInput.requestId)).state, "committed"); }));

// Given one healthy reusable idle and nonreusable live peers, pressure admission cannot delete the sole reusable floor; a context-retire claim also cannot fall back to ordinary healthy acceptance.
void test("pressure floor and context claims use fresh reusable eligibility", async () => withRoot(async root => { const f = await fixture(root, { maxLiveAgents: 3, maxConcurrentTasks: 6, maxTasksPerMesh: 20 }); const idle = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const busyA = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const busyB = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); await patchAgentStatus(root, f.mesh.meshId, busyA.agentId, { state: "busy" }); await patchAgentStatus(root, f.mesh.meshId, busyB.agentId, { state: "busy" }); await assert.rejects(reserveNewAgentCapacityWithPressure({ stateRoot: root, meshId: f.mesh.meshId, leaseId: f.lease.leaseId, gc: syntheticGcConfig(), exec: tmuxExec(new Set([idle.paneId, busyA.paneId, busyB.paneId])), tmux: "tmux" }), /no pressure GC candidate/u); const activity = await (await import("../extensions_src/utilities/orchestration_activity.ts")).readAgentActivity(root, f.mesh.meshId, idle.agentId); assert.equal(await claimIdleAgentForStop(root, f.mesh.meshId, idle.agentId, { source: "gc-context", reason: "retire only", activitySequence: activity!.sequence, staleMs: 10_000, allowContextRetire: true }), undefined); }));

// Given two process-local termination coordinators for one request, when the first attempt fails and restores admission, the delayed second attempt is fenced by the cross-process termination lock and cannot kill the reused agent.
void test("cross-process termination attempts fence a delayed kill after failure restoration", async () => withRoot(async root => {
    const f = await fixture(root);
    const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString());
    let enterKill!: () => void;
    const killing = new Promise<void>(resolve => { enterKill = resolve; });
    let releaseKill!: () => void;
    const release = new Promise<void>(resolve => { releaseKill = resolve; });
    let kills = 0;
    const exec: CommandExecutor = async (_command, args) => {
        const operation = args.find(item => ["display-message", "kill-window", "list-panes", "has-session"].includes(item));
        if (operation === "display-message") return { stdout: "10\n", stderr: "", code: 0 };
        if (operation === "kill-window") { kills += 1; enterKill(); await release; return { stdout: "", stderr: "kill failed", code: 1 }; }
        if (operation === "list-panes") return { stdout: `${target.paneId}\t0\n`, stderr: "", code: 0 };
        if (operation === "has-session") return { stdout: "", stderr: "", code: 0 };
        return { stdout: "", stderr: "", code: 0 };
    };
    const firstModuleUrl = new URL("../extensions_src/utilities/orchestration_management.ts?termination-attempt=one", import.meta.url);
    const secondModuleUrl = new URL("../extensions_src/utilities/orchestration_management.ts?termination-attempt=two", import.meta.url);
    const firstModule = await import(firstModuleUrl.href);
    const secondModule = await import(secondModuleUrl.href);
    const options = { stateRoot: root, meshId: f.mesh.meshId, agentId: target.agentId, source: "peer" as const, reason: "concurrent stop", exec, tmux: "tmux" };
    const first = firstModule.stopMeshAgentWithDisposition(options);
    await killing;
    const stopping = await readAgentSnapshot(root, f.mesh.meshId, target.agentId);
    const terminationDirectory = join(root, "meshes", f.mesh.meshId, "agents", target.agentId, "termination");
    let closeContentionObserver = () => {};
    const queued = new Promise<void>((resolve, reject) => {
        const observer = watch(terminationDirectory, (_event, filename) => {
            if (filename?.toString().startsWith(".lock.candidate.")) resolve();
        });
        closeContentionObserver = () => observer.close();
        observer.on("error", reject);
    });
    const second = secondModule.stopMeshAgentWithDisposition({ ...options, claimedRequest: stopping.stop! });
    let contentionObserved = false;
    try {
        await queued;
        await access(join(terminationDirectory, ".lock"));
        contentionObserved = true;
    } finally {
        closeContentionObserver();
        if (!contentionObserved) releaseKill();
    }
    releaseKill();
    await assert.rejects(first, /kill failed|Could not stop/u);
    const delayed = await second;
    assert.equal(kills, 1);
    assert.equal(delayed.snapshot.status.state, "idle");
    assert.equal(delayed.snapshot.stop?.state, "failed");
    await createTask(root, f.mesh.meshId, target.agentId, "safe reuse after failed stop");
    assert.equal((await readAgentSnapshot(root, f.mesh.meshId, target.agentId)).status.state, "busy");
}));

// Behavioral admission: GC claiming and activity publication share an agent lifecycle boundary. A stale heartbeat after a GC claim would incorrectly revive an agent's activity projection; type checks and atomic writes cannot observe this interleaving.
// Given a GC claim holding mesh→agent locks, when a prior runtime's non-terminal heartbeat waits for that agent lock, the heartbeat is rejected after the claim persists stopping state.
void test("GC claim fences a stale non-terminal heartbeat", async () => withRoot(async root => {
    const f = await fixture(root);
    const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString());
    const current = await readAgentActivity(root, f.mesh.meshId, target.agentId);
    let meshAcquired = false;
    let gcAgentLockHeld = false;
    let gcAgentLockHeldResolve!: () => void;
    const gcAgentLockHeldPromise = new Promise<void>(resolve => { gcAgentLockHeldResolve = resolve; });
    let releaseGcAgentLock!: () => void;
    const releaseGcAgentLockPromise = new Promise<void>(resolve => { releaseGcAgentLock = resolve; });
    const events: OrchestrationLockObservation[] = [];
    const resetObserver = setOrchestrationLockObserverForTest(async event => {
        events.push(event);
        if (event.phase === "acquired" && event.scope === "mesh" && event.meshId === f.mesh.meshId) meshAcquired = true;
        if (meshAcquired && !gcAgentLockHeld && event.phase === "acquired" && event.scope === "agent" && event.agentId === target.agentId) {
            gcAgentLockHeld = true;
            gcAgentLockHeldResolve();
            await releaseGcAgentLockPromise;
        }
    });
    try {
        const claim = claimIdleAgentForStop(root, f.mesh.meshId, target.agentId, { source: "gc-role", reason: "deterministic stale heartbeat race", activitySequence: current!.sequence, staleMs: 10_000 });
        await gcAgentLockHeldPromise;
        const at = new Date(Date.now() + 1_000).toISOString();
        const staleHeartbeat = publishAgentActivity(root, f.mesh.meshId, target.agentId, { runtimeId: target.runtimeId, phase: "running", acceptingTask: false, pendingMessages: false, phaseSince: at, observedAt: at, heartbeatAt: at, context: availableContext(10, 100_000, 100) });
        assert.deepEqual(events.map(event => `${event.phase}:${event.scope}`), ["waiting:mesh", "acquired:mesh", "waiting:agent", "acquired:agent", "waiting:agent"]);
        releaseGcAgentLock();
        assert.notEqual(await claim, undefined);
        await assert.rejects(staleHeartbeat, /cannot publish non-terminal/u);
        assert.equal((await readAgentSnapshot(root, f.mesh.meshId, target.agentId)).status.state, "stopping");
    } finally {
        resetObserver();
    }
}));

void test("replaced runtimes cannot project activity, win GC admission, or claim external work", async () => withRoot(async root => { const f = await fixture(root); const target = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); const sequence = (await import("../extensions_src/utilities/orchestration_activity.ts")).readAgentActivity(root, f.mesh.meshId, target.agentId).then(value => value!.sequence); await bindAgentRuntime(root, f.mesh.meshId, target.agentId, { runtimeId: randomUUID(), kind: "external" }); assert.equal((await readAgentSnapshot(root, f.mesh.meshId, target.agentId)).activity.phase, "unknown"); await assert.rejects(createTask(root, f.mesh.meshId, target.agentId, "stale admission"), /not accepting tasks/u); assert.equal(await claimIdleAgentForStop(root, f.mesh.meshId, target.agentId, { source: "gc-role", reason: "stale GC", activitySequence: await sequence, staleMs: 10_000 }), undefined); const worker = await agent(root, f.mesh.meshId, f.epoch.epochId, "worker", new Date().toISOString()); await createTask(root, f.mesh.meshId, worker.agentId, "external work"); await bindAgentRuntime(root, f.mesh.meshId, worker.agentId, { runtimeId: randomUUID(), kind: "external" }); await assert.rejects(claimPendingTask(root, f.mesh.meshId, worker.agentId, worker.runtimeId), /stale or unbound/u); }));
